    pub struct SrRefusedPayload {}

    /// The payload of event `sr-unavailable`: Refused for identity outage.
    ///
    /// A request that needs a session is refused because the identity service did not answer.
    #[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
