/// Mail dispatch (implementation)
///
/// One message of the mail outbox. The dispatcher submits it with its idempotency key and counts the submission; when no acknowledgement comes within 30 seconds (30000 ms, default) a timer raises em-timeout and it submits it again with the same key, and an acknowledgement records the message as sent.
///
/// Specification behavior `mail-dispatch-flow-impl`, an implementation-level machine.
pub mod mail_dispatch_flow_impl {
    use std::time::Duration;

    use serde::{Deserialize, Serialize};

    use strata_runtime::{Delivery, Isolation, Machine, Outcome, RecordError, StepError, Time};

    use crate::{records, types};

    /// The states of machine `mail-dispatch-flow-impl`.
    #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]

    pub enum State {
        /// State `mdi-idle`: Queued. Ignores `em-timeout`, `em-ack`.
        #[serde(rename = "mdi-idle")]
        MdiIdle,
        /// State `mdi-waiting`: Submitted, waiting for an acknowledgement. Ignores `em-due`.
        #[serde(rename = "mdi-waiting")]
        MdiWaiting,
        /// State `mdi-sent`: Recorded as sent. Ignores `em-due`, `em-timeout`.
        #[serde(rename = "mdi-sent")]
        MdiSent,
    }

    impl State {
        /// The state's id in the specification.
        pub fn id(self) -> &'static str {
            match self {
                State::MdiIdle => "mdi-idle",
                State::MdiWaiting => "mdi-waiting",
                State::MdiSent => "mdi-sent",
            }
        }

        /// The state with this id in the specification.
        pub fn from_id(id: &str) -> Option<State> {
            match id {
                "mdi-idle" => Some(State::MdiIdle),
                "mdi-waiting" => Some(State::MdiWaiting),
                "mdi-sent" => Some(State::MdiSent),
                _ => None,
            }
        }
    }

    /// The variables of the machine.
    #[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
    pub struct Vars {
        /// Variable `attempts`.
        pub attempts: u64,
        /// Variable `key`.
        pub key: String,
    }

    /// The payload of event `em-due`: Mail job due.
    ///
    /// A mail job reaches the dispatcher, with its idempotency key.
    #[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
    pub struct EmDuePayload {
        /// Field `key`.
        pub key: String,
        /// Field `message-id`.
        #[serde(rename = "message-id")]
        pub message_id: types::MessageId,
    }

    /// The payload of event `em-ack`: Message accepted.
    ///
    /// The adapter acknowledges the message.
    #[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
    pub struct EmAckPayload {}

    /// The payload of event `em-timeout`: No acknowledgement.
    ///
    /// The dispatcher has waited for an acknowledgement and has none.
    #[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
    pub struct EmTimeoutPayload {
        /// Field `message-id`.
        #[serde(rename = "message-id")]
        pub message_id: types::MessageId,
    }

    /// The payload of event `em-submit`: Message submitted.
    ///
    /// The dispatcher hands the message to the adapter with its idempotency key.
    #[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
    pub struct EmSubmitPayload {
        /// Field `key`.
        pub key: String,
    }

    /// The payload of event `em-recorded`: Message recorded as sent.
    ///
    /// The dispatcher records the message as sent.
    #[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
    pub struct EmRecordedPayload {}

    /// The events machine `mail-dispatch-flow-impl` receives, including those its timers fire.
    #[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
    #[serde(tag = "event", content = "payload")]
    pub enum Event {
        /// Event `em-due`: Mail job due.
        #[serde(rename = "em-due")]
        EmDue(EmDuePayload),
        /// Event `em-ack`: Message accepted.
        #[serde(rename = "em-ack")]
        EmAck(EmAckPayload),
        /// Event `em-timeout`: No acknowledgement.
        #[serde(rename = "em-timeout")]
        EmTimeout(EmTimeoutPayload),
    }

    /// The events machine `mail-dispatch-flow-impl` emits.
    #[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
    #[serde(tag = "event", content = "payload")]
    pub enum Emitted {
        /// Event `em-submit`: Message submitted.
        #[serde(rename = "em-submit")]
        EmSubmit(EmSubmitPayload),
        /// Event `em-recorded`: Message recorded as sent.
        #[serde(rename = "em-recorded")]
        EmRecorded(EmRecordedPayload),
    }

    /// The instance key: field `message-id` of record `rec-mail-message`.
    pub type Key = types::MessageId;

    /// Machine `mail-dispatch-flow-impl`, stored in record `rec-mail-message` by `message-id`.
    #[derive(Debug, Clone, Copy, Default)]
    pub struct MailDispatchFlowImpl;

    /// The refusal of a step whose arithmetic overflows or divides by zero.
    fn overflow(transition: &str) -> StepError {
        StepError::Rejected(format!(
            "transition {transition} overflowed or divided by zero"
        ))
    }

    impl Machine for MailDispatchFlowImpl {
        const NAME: &'static str = "mail-dispatch-flow-impl";

        const RECORD: &'static str = "rec-mail-message";

        const ISOLATION: Isolation = Isolation::Serializable;

        const CREATES: bool = false;

        type State = State;

        type Vars = Vars;

        type Event = Event;

        type Emitted = Emitted;

        type Key = Key;

        type Record = records::RecMailMessage;

        fn initial(_key: &Key) -> (State, Vars) {
            (
                State::MdiIdle,
                Vars {
                    attempts: 0u64,
                    key: String::from(""),
                },
            )
        }

        fn from_record(record: &records::RecMailMessage) -> Result<(State, Vars), RecordError> {
            let state = match &record.state {
                types::MessageState::Queued => State::MdiIdle,
                types::MessageState::Submitted => State::MdiWaiting,
                types::MessageState::Sent => State::MdiSent,
                other => {
                    return Err(RecordError(format!(
                        "{other:?} is not a state of machine `mail-dispatch-flow-impl`"
                    )));
                }
            };
            Ok((
                state,
                Vars {
                    attempts: record.attempts,
                    key: record.idempotency_key.clone(),
                },
            ))
        }

        fn to_record(
            key: &Key,
            state: &State,
            vars: &Vars,
            previous: Option<&records::RecMailMessage>,
        ) -> Result<records::RecMailMessage, RecordError> {
            let Some(previous) = previous else {
                return Err(
                    RecordError(
                        "machine `mail-dispatch-flow-impl` does not create records of `rec-mail-message`, and the key has none"
                            .to_string(),
                    ),
                );
            };
            Ok(records::RecMailMessage {
                message_id: key.clone(),
                idempotency_key: vars.key.clone(),
                recipient: previous.recipient.clone(),
                address: previous.address.clone(),
                template_id: previous.template_id.clone(),
                state: match state {
                    State::MdiIdle => types::MessageState::Queued,
                    State::MdiWaiting => types::MessageState::Submitted,
                    State::MdiSent => types::MessageState::Sent,
                },
                attempts: vars.attempts,
                provider_reference: previous.provider_reference.clone(),
            })
        }

        fn step(
            state: &State,
            vars: &Vars,
            event: &Event,
            _now: Time,
        ) -> Result<Outcome<Self>, StepError> {
            match (state, event) {
                (State::MdiIdle, Event::EmDue(payload)) => {
                    let mut next = vars.clone();
                    next.attempts = next
                        .attempts
                        .checked_add(1u64)
                        .ok_or(overflow("mdi-submit"))?;
                    next.key = payload.key.clone();
                    let emitted_3 = Emitted::EmSubmit(EmSubmitPayload {
                        key: next.key.clone(),
                    });
                    let timer_4 = Event::EmTimeout(EmTimeoutPayload {
                        message_id: types::MessageId(payload.message_id.0),
                    });
                    Ok(Outcome::to(State::MdiWaiting, next)
                        .emit("mail-service", Delivery::AtLeastOnce, emitted_3)
                        .set_timer("ack-timeout", Duration::from_millis(30000), timer_4))
                }
                (State::MdiWaiting, Event::EmTimeout(payload)) => {
                    let mut next = vars.clone();
                    next.attempts = next
                        .attempts
                        .checked_add(1u64)
                        .ok_or(overflow("mdi-resubmit"))?;
                    let emitted_2 = Emitted::EmSubmit(EmSubmitPayload {
                        key: next.key.clone(),
                    });
                    let timer_3 = Event::EmTimeout(EmTimeoutPayload {
                        message_id: types::MessageId(payload.message_id.0),
                    });
                    Ok(Outcome::to(State::MdiWaiting, next)
                        .emit("mail-service", Delivery::AtLeastOnce, emitted_2)
                        .set_timer("ack-timeout", Duration::from_millis(30000), timer_3))
                }
                (State::MdiWaiting, Event::EmAck(_)) => {
                    Ok(Outcome::to(State::MdiSent, vars.clone())
                        .emit(
                            "automation-worker",
                            Delivery::AtMostOnce,
                            Emitted::EmRecorded(EmRecordedPayload {}),
                        )
                        .cancel_timer("ack-timeout"))
                }
                (State::MdiSent, Event::EmAck(_)) => Ok(Outcome::to(State::MdiSent, vars.clone())),
                _ => Ok(Outcome::to(*state, vars.clone())),
            }
        }
    }
}

/// Mail adapter (implementation)
///
/// The adapter of the mail contract with its table of idempotency keys, two slots k1 and k2. A slot holds the number of times its message was delivered; a slot above zero means the key was seen. A key is delivered once and every submission of it is acknowledged. The table is the set of effect records of the adapter, so the machine is one unit and has no keyed instances. An acknowledgement follows its submission by 200 ms (default). One model tick is 100 ms here (timeScale 100), so the model delay of two ticks is the 200 ms.
