    #[derive(Debug, Clone, Copy, Default)]
    pub struct ColourSwitchFlowImpl;

    impl Machine for ColourSwitchFlowImpl {
        const NAME: &'static str = "colour-switch-flow-impl";

        const RECORD: &'static str = "rec-platform-environment";

        const ISOLATION: Isolation = Isolation::Serializable;

        const CREATES: bool = false;

        type State = State;

        type Vars = Vars;

        type Event = Event;

        type Emitted = Emitted;

        type Key = Key;

        type Record = records::RecPlatformEnvironment;

        fn initial(_key: &Key) -> (State, Vars) {
            (
                State::CsiBlue,
                Vars {
                    verified: false,
                    withdrawn: false,
                    live_colour: types::ColourId(String::from("blue")),
                },
            )
        }

        fn from_record(
            record: &records::RecPlatformEnvironment,
        ) -> Result<(State, Vars), RecordError> {
            let state = State::from_id(&record.state).ok_or_else(|| {
                RecordError(format!(
                    "{:?} is not a state of machine `colour-switch-flow-impl`",
                    record.state
                ))
            })?;
            Ok((
                state,
                Vars {
                    verified: record.green_verified,
                    withdrawn: record.green_withdrawn,
                    live_colour: record.live_colour.clone(),
                },
            ))
        }

        fn to_record(
            key: &Key,
            state: &State,
            vars: &Vars,
            previous: Option<&records::RecPlatformEnvironment>,
        ) -> Result<records::RecPlatformEnvironment, RecordError> {
            let Some(previous) = previous else {
                return Err(
                    RecordError(
                        "machine `colour-switch-flow-impl` does not create records of `rec-platform-environment`, and the key has none"
                            .to_string(),
                    ),
                );
            };
            Ok(records::RecPlatformEnvironment {
                environment_id: key.clone(),
                kind: previous.kind.clone(),
                account: previous.account.clone(),
                region: previous.region.clone(),
                definition_commit: previous.definition_commit.clone(),
                live_colour: vars.live_colour.clone(),
                green_verified: vars.verified,
                green_withdrawn: vars.withdrawn,
                state: state.id().to_string(),
            })
        }

        fn step(
            state: &State,
            vars: &Vars,
            event: &Event,
            _now: Time,
        ) -> Result<Outcome<Self>, StepError> {
            match (state, event) {
                (State::CsiBlue, Event::CsGreenDeployed(_)) => {
                    Ok(Outcome::to(State::CsiVerifying, vars.clone()))
                }
                (State::CsiBlue, Event::CsRequest(_)) => {
                    Ok(Outcome::to(State::CsiBlue, vars.clone()).emit(
                        "gateway",
                        Delivery::AtMostOnce,
                        Emitted::CsServedBlue(CsServedBluePayload {}),
                    ))
                }
                (State::CsiVerifying, Event::CsGreenVerified(_)) => {
                    let mut next = vars.clone();
                    next.verified = true;
                    Ok(Outcome::to(State::CsiVerifying, next))
                }
                (State::CsiVerifying, Event::CsSwitchRequested(_)) => {
                    if !vars.verified {
                        Ok(Outcome::to(State::CsiVerifying, vars.clone()).emit(
                            "release-controller",
                            Delivery::AtMostOnce,
                            Emitted::CsSwitchRefused(CsSwitchRefusedPayload {}),
                        ))
                    } else {
                        if vars.verified {
                            let mut next = vars.clone();
                            next.live_colour =
                                types::ColourId(::std::string::String::from("green"));
                            let emitted_2 = Emitted::CsTrafficGreen(CsTrafficGreenPayload {});
                            Ok(Outcome::to(State::CsiGreen, next).emit(
                                "release-controller",
                                Delivery::AtLeastOnce,
                                emitted_2,
                            ))
                        } else {
                            Ok(Outcome::to(*state, vars.clone()))
                        }
                    }
                }
                (State::CsiVerifying, Event::CsRequest(_)) => {
                    Ok(Outcome::to(State::CsiVerifying, vars.clone()).emit(
                        "gateway",
                        Delivery::AtMostOnce,
                        Emitted::CsServedBlue(CsServedBluePayload {}),
                    ))
                }
                (State::CsiGreen, Event::CsRequest(_)) => {
                    Ok(Outcome::to(State::CsiGreen, vars.clone()).emit(
                        "gateway",
                        Delivery::AtMostOnce,
                        Emitted::CsServedGreen(CsServedGreenPayload {}),
                    ))
                }
                (State::CsiGreen, Event::CsRollbackRequested(_)) => {
                    let mut next = vars.clone();
                    next.withdrawn = true;
                    next.live_colour = types::ColourId(::std::string::String::from("blue"));
                    let emitted_3 = Emitted::CsTrafficBlue(CsTrafficBluePayload {});
                    Ok(Outcome::to(State::CsiBlue, next).emit(
                        "release-controller",
                        Delivery::AtLeastOnce,
                        emitted_3,
                    ))
                }
                _ => Ok(Outcome::to(*state, vars.clone())),
            }
        }
    }
